#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn keys_unique_and_placeholders_match() {
        let mut seen = std::collections::HashSet::new();
        for (k, v) in ROWS {
            assert!(seen.insert(*k), "duplicate key {k}");
            let n = k.matches("{}").count();
            for t in v {
                assert_eq!(t.matches("{}").count(), n, "placeholder mismatch in {k} -> {t}");
            }
        }
    }

    /// Every fixed text the program shows through tr()/trf() has its four translations.
    #[test]
    fn every_text_is_translated() {
        fn walk(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
            for e in std::fs::read_dir(dir).unwrap().flatten() {
                let p = e.path();
                if p.is_dir() {
                    walk(&p, out);
                } else if p.extension().is_some_and(|x| x == "rs") {
                    out.push(p);
                }
            }
        }
        let mut files = Vec::new();
        walk(&std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src"), &mut files);
        let keys: std::collections::HashSet<&str> = ROWS.iter().map(|(k, _)| *k).collect();
        let mut missing = std::collections::BTreeSet::new();
        let mut checked = 0;
        for f in files {
            let s = std::fs::read_to_string(&f).unwrap();
            for start in ["tr(\"", "trf(\""] {
                let mut rest = s.as_str();
                while let Some(i) = rest.find(start) {
                    // only the functions themselves, not names ending in tr (e.g. attr)
                    let before = rest[..i].chars().last();
                    rest = &rest[i + start.len()..];
                    if before.is_some_and(|c| c.is_alphanumeric() || c == '_') {
                        continue;
                    }
                    let mut end = 0;
                    let b = rest.as_bytes();
                    while end < b.len() && b[end] != b'"' {
                        end += if b[end] == b'\\' { 2 } else { 1 };
                    }
                    let raw = &rest[..end.min(rest.len())];
                    let text = raw.replace("\\n", "\n").replace("\\\"", "\"");
                    checked += 1;
                    if !keys.contains(text.as_str()) {
                        missing.insert(format!("{}: {}", f.file_name().unwrap().to_string_lossy(), raw));
                    }
                }
            }
        }
        // names kept in lists and translated where they're shown
        let src = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
        for (file, from, to) in [
            ("settings_ui.rs", "const TABS", "\n"),
            ("device_ui.rs", "const TABS", "\n"),
            ("settings_ui.rs", "let sizes =", "// two sliders"),
            ("settings_ui.rs", "let units = [", "for (a, al"),
            ("model.rs", "LASER_SOURCES", "];"),
            ("vartext.rs", "EVAL_TYPES", "];"),
        ] {
            let s = std::fs::read_to_string(src.join(file)).unwrap();
            let Some(i) = s.find(from) else { continue };
            let part = &s[i..];
            let part = &part[..part.find(to).unwrap_or(part.len())];
            for (n, piece) in part.split('"').enumerate() {
                if n % 2 == 1 && piece.chars().any(|c| c.is_alphabetic()) {
                    checked += 1;
                    if !keys.contains(piece) {
                        missing.insert(format!("{file}: {piece}"));
                    }
                }
            }
        }
        assert!(checked > 1000, "only {checked} texts found");
        assert!(missing.is_empty(), "untranslated texts:\n{}", missing.into_iter().collect::<Vec<_>>().join("\n"));
    }

    #[test]
    fn lookup_and_fill() {
        set(Lang::De);
        assert_eq!(tr("Salva"), "Speichern");
        assert_eq!(trf("Raggruppati {} oggetti", &[&3]), "3 Objekte gruppiert");
        set(Lang::It);
        assert_eq!(tr("Salva"), "Salva");
        assert_eq!(Lang::from_code("fr-CA"), Some(Lang::Fr));
    }
}
